try{
 if($method==='GET'){$items=studentConversationMessages($pdo,(int)$conversation['id'],$userId,max(0,(int)($_GET['after_id']??0)),studentCommunicationLimit($_GET['limit']??50,50,100));foreach($items as &$message){foreach($message['attachments'] as &$file){$endpoint=rtrim(BASE_URL,'/').'/api/v1/student/conversations/'.$conversation['uuid'].'/messages/'.$message['uuid'].'/attachments/'.$file['uuid'];$file['view_endpoint']=$endpoint;$file['download_endpoint']=$endpoint.'?download=1';$file['requires_bearer']=true;}unset($file);}unset($message);apiResponse(true,'',['conversation'=>['uuid'=>$conversation['uuid'],'subject'=>$conversation['objet'],'type'=>$conversation['type_conversation'],'status'=>$conversation['statut'],'participants'=>studentConversationParticipants($pdo,(int)$conversation['id'])],'items'=>$items]);}
